 import { supabase } from '../lib/supabase'

export async function checkUserSubscription(userId) {
    if (!userId) return false

    try {
        // Check for a premium payment that was successful and hasn't expired
        const { data, error } = await supabase
            .from('subscription_payments')
            .select('id, expires_at, created_at')
            .eq('user_id', userId)
            .eq('type', 'premium')
            .eq('status', 'success')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle()

        if (error) throw error
        if (!data) return false

        // If we have an expires_at date, check if it's still valid
        if (data.expires_at) {
            const now = new Date()
            const expiry = new Date(data.expires_at)
            if (expiry < now) {
                // Subscription expired
                return false
            }
            return true
        }

        // Fallback: if no expiry date, assume 30 days from creation
        const created = new Date(data.created_at)
        const expiry = new Date(created)
        expiry.setDate(expiry.getDate() + 30)
        return expiry > new Date()
    } catch (error) {
        console.error('Error checking subscription:', error)
        return false
    }
}
